(function(){
'use strict';
const E=RivieraEngine,W=RivieraWorld, LS='rivieranoir_v4_save', LS_ROOM='rivieranoir_v2_online', LS_PROFILE='rivieranoir_v4_profile';
const app=document.getElementById('app');
const ui={customProfile:{name:'',bio:'',nickname:'',archetype:'Indépendant',contacts:'',notes:'',equipment:'',origin:'',goal:'',flaw:'',contactId:null,flawId:null,portrait:'yanis',color:'#61dfcf',skills:{physique:0,ruse:2,technique:1,bagout:1,pilotage:0},specialty:'ruse'},recoveryKey:'',localCustom:{},localTarget:0,localEditing:false,page:'menu',creatorFor:'solo',mode:'solo',aiMode:false,aiDraft:'',difficulty:'normal',hero:'custom',actor:'perso_solo',count:4,names:['Gauthier','Yanis','Mathieu','Juliette'],nickname:'',joinCode:'',onlineAction:'create',game:null,localVotes:{},localTurn:0,online:null,ws:null,ownVote:null,error:'',notice:'',showRules:false,selectedMission:'belladone',onlineSession:null,reconnecting:false};
const hero=(id)=>ui.game?.crew?.find(x=>x.id===id)||ui.online?.players?.find(x=>x.character===id)?.profile||(id==='custom'?{...ui.customProfile,id:'perso_solo',role:'Personnage original',custom:true}:null)||E.HEROES.find(x=>x.id===id)||E.HEROES[0];
const makeProfile=(profile,id='perso_solo')=>({...JSON.parse(JSON.stringify(profile)),id,role:profile.archetype||'Personnage original',custom:true});
const portraitFor=(x)=>portrait(x.portrait||x.id);
const pointsLeft=()=>4-Object.values(ui.customProfile.skills).reduce((a,b)=>a+b,0);
const validSkills=(p)=>[...Object.values(p.skills)].sort((a,b)=>b-a).join(',')==='2,1,1,0,0';
function storeProfile(){try{localStorage.setItem(LS_PROFILE,JSON.stringify(ui.customProfile));}catch(e){}}
function profileEditor(){const p=ui.customProfile;const remaining=pointsLeft();const valid=validSkills(p);return `<div class="sheet-card">
 <div class="sheet-photo"><div class="sheet-picture">${portraitFor(p)}</div><div class="sheet-swatch" style="background:${p.color}"></div><span>FICHE D’IDENTITÉ · RIVIERA D’ORO</span><h2>${h(p.name||'Votre personnage')}</h2><p>${h(p.bio||'Choisissez un passé, un objectif et un point faible. Aucune information du scénario ne vous sera donnée à l’avance.')}</p></div>
 <div class="sheet-fields">
 <div class="sheet-block"><span class="eyebrow">01 / IDENTITÉ</span><label class="input-label">Nom du personnage<input data-field="profile-name" maxlength="22" value="${h(p.name)}" placeholder="Ex. : Alessia Costa" /></label><div class="sheet-pair"><label class="input-label">Surnom<input data-field="profile-nickname" maxlength="30" value="${h(p.nickname||'')}" placeholder="Ex. : Le Renard" /></label><label class="input-label">Archétype<select data-field="profile-archetype">${['Indépendant','Escroc','Pilote','Infiltré','Fixeur','Technicien','Négociateur'].map(x=>`<option value="${x}" ${p.archetype===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="input-label">Métier ou passé<input data-field="profile-bio" maxlength="110" value="${h(p.bio)}" placeholder="Ex. : mécanicienne, ex-agent de sécurité, escroc…" /></label><div class="sheet-pair"><label class="input-label">Motivation<input data-field="profile-goal" maxlength="80" value="${h(p.goal||'')}" placeholder="Pourquoi Riviera ?" /></label><label class="input-label">Faille personnelle<input data-field="profile-flaw" maxlength="80" value="${h(p.flaw||'')}" placeholder="Dette, peur, rivalité…" /></label></div></div>
 <div class="sheet-block"><span class="eyebrow">02 / APPARENCE</span><div class="portrait-picks">${[...E.HEROES.map(x=>({id:x.id,name:x.name})),...Array.from({length:12},(_,i)=>({id:'extra-'+String(i+1).padStart(2,'0'),name:'Profil alternatif '+(i+1)}))].map(x=>`<button type="button" data-action="profile-portrait" data-value="${x.id}" class="portrait-choice ${p.portrait===x.id?'selected':''}" title="Portrait ${h(x.name)}" aria-label="Portrait ${h(x.name)}">${portrait(x.id)}</button>`).join('')}</div><div class="color-picks">${['#b5a5ff','#61dfcf','#ffc17b','#ff82a1','#75bfff','#8fe5a8'].map(c=>`<button type="button" data-action="profile-color" data-value="${c}" class="color-choice ${p.color===c?'selected':''}" style="background:${c}" aria-label="Couleur ${c}"></button>`).join('')}</div></div>
 <div class="sheet-block"><span class="eyebrow">03 / CARACTÉRISTIQUES — FICHE JDR</span><p class="minor">Répartissez exactement <b>+2, +1, +1, 0, 0</b> parmi vos cinq caractéristiques. En action : <b>2D6 + caractéristique + spécialité</b>.</p><div class="skill-points"><b>${valid?'Répartition validée':'Points à attribuer'}</b><span class="${valid?'valid':''}">${remaining} / 4 restants</span></div>
 ${Object.entries(E.SKILL_LABEL).map(([key,label])=>`<div class="skill-picker"><span><b>${h(label)}</b><small>${h(E.SKILL_HELP?.[key]||'')}</small></span><div><button data-action="profile-minus" data-value="${key}" ${p.skills[key]<=0?'disabled':''} aria-label="Réduire ${h(label)}">−</button><strong>+${p.skills[key]}</strong><button data-action="profile-plus" data-value="${key}" ${p.skills[key]>=2||remaining<=0?'disabled':''} aria-label="Augmenter ${h(label)}">+</button></div></div>`).join('')}</div>
 <div class="sheet-block"><span class="eyebrow">04 / SPÉCIALITÉ</span><p class="minor">Choisissez votre spécialité. Elle ajoute <b>+1</b> sur les jets de cette caractéristique.</p><div class="specialty-options">${Object.entries(E.SKILL_LABEL).map(([key,label])=>`<button data-action="profile-specialty" data-value="${key}" class="specialty ${p.specialty===key?'active':''}">${p.specialty===key?'◆':'◇'} ${h(label)}</button>`).join('')}</div></div>
 <div class="sheet-block"><span class="eyebrow">05 / VOS ALLIÉS · CHOIX AVEC CONSÉQUENCES</span><p class="minor">Choisissez un contact : il peut ouvrir une scène ou ajouter +1 à des jets précis. Cette relation sera réellement prise en compte.</p><div class="trait-grid">${W.CONTACTS.map(c=>`<button type="button" data-action="profile-contact" data-value="${c.id}" class="trait-card ${p.contactId===c.id?'selected':''}"><b>${h(c.name)}</b><small>${h(c.place)}</small><span>${h(c.desc)}</span></button>`).join('')}</div></div>
 <div class="sheet-block"><span class="eyebrow">06 / DÉFAUT · CONSÉQUENCE EN JEU</span><p class="minor">Un défaut est obligatoire : dette, handicap, méfiance ou impulsivité se traduisent par des malus et des réactions du monde.</p><div class="trait-grid">${W.FLAWS.map(fl=>`<button type="button" data-action="profile-flaw-id" data-value="${fl.id}" class="trait-card flaw ${p.flawId===fl.id?'selected':''}"><b>${h(fl.name)}</b><span>${h(fl.desc)}</span></button>`).join('')}</div></div>
 <div class="sheet-block"><span class="eyebrow">07 / CARNET PERSONNEL</span><div class="sheet-pair"><label class="input-label">Contacts supplémentaires (récit libre)<input data-field="profile-contacts" maxlength="100" value="${h(p.contacts||'')}" placeholder="Anciens amis, rivalités..." /></label><label class="input-label">Équipement narratif<input data-field="profile-equipment" maxlength="100" value="${h(p.equipment||'')}" placeholder="Souvenirs, tenue, objets sans bonus" /></label></div><label class="input-label">Notes personnelles<input data-field="profile-notes" maxlength="160" value="${h(p.notes||'')}" placeholder="Ce qui définit votre personnage…" /></label></div>
 </div></div>`;}
function creator(){const valid=ui.customProfile.name.trim()&&validSkills(ui.customProfile)&&ui.customProfile.contactId&&ui.customProfile.flawId;return `${header()}<main class="creator-page"><div class="creator-top"><div><span class="eyebrow">ATELIER DU PERSONNAGE · VOTRE AVENTURE COMMENCE ICI</span><h1>Créez votre <em>identité.</em></h1><p>Votre fiche originale de GTA Riviera : cinq caractéristiques, spécialité, histoire et apparence. Aucune connaissance du scénario n'est imposée.</p></div><button class="btn btn-outline" data-action="creator-back">← Retour</button></div>${profileEditor()}<div class="creator-actions"><span>${valid?'✓ Personnage prêt pour la mission 1':'Nom, +2/+1/+1/0/0, un contact et un défaut obligatoires.'}</span><button class="btn btn-primary btn-large" data-action="finish-creator" ${!valid?'disabled':''}>ENREGISTRER MON PERSONNAGE →</button></div>${ui.error?`<div class="toast error">${h(ui.error)}</div>`:''}${rules()}</main>`;}
const h=(x)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=(id)=>window.RivieraAssetUrls?.[id]||'assets/'+id+'.webp';
const portrait=(id)=>`<img src="${asset('portrait-'+id)}" alt="" loading="lazy"/>`;
const artFor=(scene)=>{if(/^(debt|ending_debt)/.test(scene))return 'lucien';if(/^(convoy|ending_convoy)/.test(scene))return scene==='convoy_load'?'docks':'chase';if(/^(gala|ending_gala)/.test(scene))return scene==='gala_intro'?'villa':'party';if(scene==='belle_open')return 'skyline';if(scene==='belle_brief')return 'lucien';if(/^belle_(barroom|prep|stairs|suite|rivals|exit)$/.test(scene))return 'belladone';if(scene==='belle_service')return 'infiltration';if(scene==='belle_terrace')return 'villa';if(scene==='belle_exit'||scene==='ending_belle_partial')return 'chase';if(scene==='intro'||scene==='watchshop'||scene==='ending_lucien')return 'belladone';if(scene==='lucien'||scene==='finale')return 'lucien';if(scene==='docks'||scene==='warehouse'||scene==='vault')return 'docks';if(scene==='escape'||scene==='ending_trapped'||scene==='ending_vanish')return 'chase';if(scene==='station'||scene==='ending_police')return 'citymap';if(scene==='mission_hub'||scene==='crossroads')return 'citymap';return 'port';};
const hasServer=location.protocol==='http:'||location.protocol==='https:';
const range=(x,min,max)=>Math.max(min,Math.min(max,x));
function save(){if(ui.mode==='online'||!ui.game)return;try{localStorage.setItem(LS,JSON.stringify({game:ui.game,mode:ui.mode,hero:ui.hero,actor:ui.actor,names:ui.names,count:ui.count,difficulty:ui.difficulty,customProfile:ui.customProfile,localCustom:ui.localCustom,localVotes:ui.localVotes,localTurn:ui.localTurn}));}catch(e){}}
function load(){try{const p=JSON.parse(localStorage.getItem(LS));if(!p||!p.game||![1,4,5].includes(p.game.version)||!E.getScene(p.game))return null;W.initialize(p.game);return p;}catch(e){return null;}}
function header(){return `<header class="masthead"><div class="brandmark"><span class="brand-sun">◈</span><span>GTA <b>RIVIERA</b><small>CRIME · LOYAUTÉ · CONSÉQUENCES</small></span></div><div class="header-right"><span class="episode">V7 · SCÉNARIOS 01 → 05</span>${ui.page==='play'?'<button class="btn btn-subtle btn-xs" data-action="home">☷ Menu</button>':''}</div></header>`;}
function menu(){const saved=load();return `${header()}<main class="landing"><section class="hero-banner"><div class="skyline"><img src="${asset('hero')}" alt="Riviera au soleil couchant avec les membres de l’équipe" /></div><div class="hero-text"><div class="eyebrow">UN POLAR INTERACTIF · CÔTE D’AZUR, 1991</div><h1>GTA<br/><em>RIVIERA</em></h1><p>Une campagne, des destins liés. Chaque choix laisse une trace dans la ville, chaque personnage peut faire basculer l’histoire.</p><div class="feature-line"><span>✧ Scénario 1 dès le début</span><span>⚄ Jets de 2D6</span><span>◈ Vos propres personnages</span></div><button class="btn btn-primary hero-creator-btn" data-action="open-creator">＋ CRÉER MON PERSONNAGE</button></div></section>
<section class="menu-panel"><div class="section-heading"><span>01 / CHOISIR LE MODE</span><h2>Comment voulez-vous jouer ?</h2></div><div class="mode-cards"><button class="mode-card ${ui.mode==='solo'?'selected':''}" data-action="mode" data-value="solo"><span class="mode-icon">◉</span><b>SOLO</b><small>Vous dirigez l’équipe et choisissez ses actions.</small></button><button class="mode-card ${ui.mode==='local'?'selected':''}" data-action="mode" data-value="local"><span class="mode-icon">♧</span><b>COOPÉRATION LOCALE</b><small>2 à 4 joueurs, votes à tour de rôle sur un écran.</small></button><button class="mode-card ${ui.mode==='online'&&!ui.aiMode?'selected':''}" data-action="mode" data-value="online"><span class="mode-icon">⌁</span><b>MULTIJOUEUR EN LIGNE</b><small>2 à 4 joueurs, salon privé avec code.</small></button><button class="mode-card ${ui.mode==='online'&&ui.aiMode?'selected':''}" data-action="ai-mode"><span class="mode-icon">✦</span><b>MJ IA · BÊTA</b><small>Actions libres, scénario fidèle. Seul ou à 4.</small></button></div>
<div class="entry-promo"><div class="entry-image"><img src="${asset('portrait-yanis')}" alt="Portrait d’un personnage" /></div><div><span class="eyebrow">VOTRE HISTOIRE, VOS RÈGLES</span><h2>Avant le premier contrat, créez votre protagoniste.</h2><p>Nom, portrait, histoire, cinq caractéristiques (+2/+1/+1/0/0) et spécialité. Ou choisissez l’un des quatre profils proposés.</p></div><button class="btn btn-primary" data-action="open-creator">CRÉER MON PERSONNAGE →</button></div><div class="section-heading mission-heading"><span>02 / CAMPAGNE DANS L’ORDRE</span><h2>Quelle mission voulez-vous commencer ?</h2></div><div class="mission-grid">${E.MISSIONS.map((m,i)=>{const locked=m.id!=='belladone';return `<button class="mission-card ${ui.selectedMission===m.id?'selected':''}" data-action="mission" data-value="${m.id}" ${locked?'disabled title="Disponible après le scénario 1"':''}><img src="${asset(m.image)}" alt="" loading="lazy"/><span class="mission-shade"></span><span class="mission-info"><small>${h(m.tag)}</small><b>${h(m.name)}</b><span>${h(m.desc)}</span><em>${locked?'🔒 APRÈS SCÉNARIO 1':h(m.length)+' · COMMENCER ICI'}</em></span></button>`;}).join('')}</div><div class="setup-grid"><div class="setup-block"><div class="field-title">${ui.mode==='solo'?'Votre personnage principal':ui.mode==='online'?'Votre personnage':'Les membres du groupe'}</div>${ui.mode==='local'?localSetup():characterSetup()}
${ui.mode==='online'?`<div class="room-form"><div class="field-title">Jouer ensemble</div><div class="tabrow"><button class="tab ${ui.onlineAction==='create'?'active':''}" data-action="online-action" data-value="create">Créer un salon</button><button class="tab ${ui.onlineAction==='join'?'active':''}" data-action="online-action" data-value="join">Rejoindre</button><button class="tab ${ui.onlineAction==='recover'?'active':''}" data-action="online-action" data-value="recover">Reprendre une campagne</button></div><label class="input-label">Votre pseudo<input data-field="nickname" maxlength="22" placeholder="Votre nom" value="${h(ui.nickname)}" /></label>${ui.onlineAction!=='create'?`<label class="input-label">Code du salon<input data-field="joinCode" maxlength="6" placeholder="EX : RIV47" value="${h(ui.joinCode)}" /></label>`:''}${ui.onlineAction==='recover'?`<label class="input-label">Clé privée de récupération<input data-field="recoveryKey" maxlength="24" placeholder="Clé donnée à l’hôte" value="${h(ui.recoveryKey)}" /></label>`:''}${!hasServer?'<p class="warning">Le mode en ligne fonctionne lorsque le jeu est lancé avec son serveur Node.js (instructions dans le pack).</p>':''}</div>`:''}
</div><div class="setup-block"><div class="field-title">Difficulté des jets</div><div class="difficulty-select"><button data-action="difficulty" data-value="facile" class="difficulty ${ui.difficulty==='facile'?'active':''}">Cinématique<small>−2 aux seuils</small></button><button data-action="difficulty" data-value="normal" class="difficulty ${ui.difficulty==='normal'?'active':''}">Standard<small>2D6 · règles du JDR</small></button><button data-action="difficulty" data-value="difficile" class="difficulty ${ui.difficulty==='difficile'?'active':''}">Impitoyable<small>+2 aux seuils</small></button></div><div class="story-recap"><b>ÉPISODE 01 · LA NUIT DU BELLADONE</b><p>Vous arrivez à Riviera. Lucien ne vous a pas encore donné de contrat. Personne ne connaît le dossier Nérée : vos choix feront l’histoire.</p><button class="text-link" data-action="rules">Voir les règles et le fonctionnement →</button></div></div></div>
<div class="start-area"><button class="btn btn-primary btn-large" data-action="start">${ui.mode==='online'?(ui.onlineAction==='create'?'CRÉER LE SALON':ui.onlineAction==='recover'?'REPRENDRE LA CAMPAGNE':'REJOINDRE LE SALON'):'COMMENCER L’AVENTURE'} <span>↗</span></button>${saved?'<button class="btn btn-outline" data-action="continue">↪ Reprendre la sauvegarde</button>':''}</div>${ui.error?`<p class="warning" role="alert">${h(ui.error)}</p>`:''}
</section><footer class="footer-note">GTA RIVIERA · CAMPAGNE DEPUIS LE SCÉNARIO 1 — Une adaptation interactive originale de votre campagne de jeu de rôle.</footer></main>${rules()}`;}
function characterSetup(){return `<div class="characters">${E.HEROES.map(x=>`<button data-action="hero" data-value="${x.id}" class="character ${ui.hero===x.id?'selected':''}"><span class="avatar photo" style="--hero:${x.color}">${portraitFor(x)}</span><span><b>${x.name}</b><small>${x.role}</small></span><span class="character-check">${ui.hero===x.id?'●':'○'}</span></button>`).join('')}<button data-action="hero" data-value="custom" class="character create-character ${ui.hero==='custom'?'selected':''}"><span class="avatar" style="--hero:#62e1d4">＋</span><span><b>CRÉER MON PERSONNAGE</b><small>Nom, portrait, histoire et compétences</small></span></button></div>${ui.hero==='custom'?`<div class="selected-profile"><span class="eyebrow">MON PERSONNAGE</span><p>${h(ui.customProfile.name||'Fiche à compléter')}</p><button data-action="open-creator" class="btn btn-primary btn-xs">${ui.customProfile.name?'MODIFIER MA FICHE':'CRÉER MA FICHE'} →</button></div>`:`<p class="minor">${h(hero(ui.hero).bio)}</p>`}`;}
function localSetup(){return `<div class="player-count"><span>Nombre de joueurs</span><div><button data-action="count" data-value="-1" aria-label="Moins">−</button><b>${ui.count}</b><button data-action="count" data-value="1" aria-label="Plus">+</button></div></div><div class="local-players">${E.HEROES.slice(0,ui.count).map((x,i)=>{const y=ui.localCustom[i]||x;return `<label><span class="avatar sm photo" style="--hero:${y.color}">${portraitFor(y)}</span><span class="player-role">${h(y.name)}<small>${h(y.role)}</small></span><input data-field="name-${i}" maxlength="22" value="${h(ui.names[i])}" aria-label="Pseudo du joueur ${i+1}"/></label>`}).join('')}</div><button class="btn btn-outline btn-xs" data-action="toggle-local-editor">${ui.localEditing?'FERMER L’ATELIER':'＋ CRÉER UN PERSONNAGE POUR UN JOUEUR'}</button>${ui.localEditing?`<div class="local-assignment"><div class="field-title">Choisissez le joueur à personnaliser</div><div class="tabrow">${Array.from({length:ui.count},(_,i)=>`<button data-action="local-target" data-value="${i}" class="tab ${ui.localTarget===i?'active':''}">Joueur ${i+1}</button>`).join('')}</div><button class="btn btn-primary" data-action="open-local-creator">CRÉER / MODIFIER LA FICHE DU JOUEUR ${ui.localTarget+1}</button></div>`:''}<p class="minor">Chaque joueur vote à son tour. En cas d’égalité, le vote du premier joueur départage.</p>`;}
function rules(){return ui.showRules?`<div class="overlay"><section class="modal"><button class="close" data-action="rules">✕</button><div class="eyebrow">RÈGLES ORIGINALES DU JDR</div><h2>2D6 et des choix qui comptent.</h2><p>La campagne commence à Riviera d’Oro, avant le premier rendez-vous avec Lucien. Aucun personnage ne connaît déjà Nérée. Vous construisez son histoire.</p><p>Pour un test, lancez <strong>2D6 + caractéristique + 1 si la spécialité correspond</strong>. Seuils : 7 standard, 9 difficile, 11 très difficile, 13 exploit. Un 12 naturel (double 6) est une réussite critique et un 2 naturel (double 1) un échec critique.</p><p>La fiche donne +2/+1/+1/0/0 en Physique, Ruse, Technique, Bagout et Pilotage. En multijoueur, chaque joueur vote, puis l’hôte valide.</p><p>Les salons en ligne peuvent être repris si la base de données du serveur est activée. Conservez la clé privée de reprise de l’hôte ainsi qu’un export de secours.</p><button class="btn btn-primary" data-action="rules">COMPRIS</button></section></div>`:'';}
function miniStat(label,num,typ){const val=typ==='heat'?num/10:typ==='money'?Math.min(num/3000,1):typ==='morale'?num/5:(num+5)/10;return `<div class="stat"><div class="stat-top"><span>${label}</span><strong>${typ==='money'?num.toLocaleString('fr-FR')+' €':typ==='heat'?num+'/10':num>0?'+'+num:num}</strong></div><div class="meter"><div class="meter-fill ${typ}" style="width:${range(val,0,1)*100}%"></div></div></div>`;}

function cityMap(s,online){
 const here=W.currentDistrict(s),explore=W.canExplore(s),host=!online||!!ui.online?.isHost;
 const localPlaces=W.STORES.filter(p=>p.districtId===here.id).concat(W.SERVICES.filter(p=>p.districtId===here.id));
 const locals=W.NPCS.filter(n=>n.districtId===here.id),tasks=W.ACTIVITIES.filter(a=>a.districtId===here.id);
 return `<section class="riviera-explore" id="explorer-riviera"><div class="explore-heading"><div><span class="eyebrow">GTA RIVIERA V6 · VILLE INTERACTIVE</span><h2>Explorer la Riviera</h2><p>Choisissez un quartier pour vous déplacer et découvrir ses commerces, contacts et activités.</p></div><strong>📍 ${h(here.name)}</strong></div>
 <div class="riviera-map-canvas"><img src="${asset('citymap')}" alt="Carte illustrée de Riviera" loading="lazy"/><div class="riviera-map-shade"></div>${W.DISTRICTS.map(d=>`<button type="button" class="district-pin ${here.id===d.id?'active':''}" data-action="world-travel" data-value="${d.id}" style="left:${d.x}%;top:${d.y}%" aria-label="${here.id===d.id?'Quartier actuel : ':'Voyager vers '}${h(d.name)}" ${!explore||!host||here.id===d.id?'disabled':''}><span>${d.icon}</span><b>${h(d.name)}</b></button>`).join('')}</div>
 <div class="district-details"><div class="district-description"><small>${h(here.tag)} · ${s.city?.visited?.[here.id]||1} visite(s)</small><h3>${here.icon} ${h(here.name)}</h3><p>${h(here.desc)}</p>${localPlaces.length?`<p class="district-local-label">Sur place : ${localPlaces.map(p=>h(p.name)).join(' · ')}</p>`:'<p class="district-local-label">Aucun commerce dans ce quartier.</p>'}</div>
 <div class="district-activities">${!explore?'<p class="explore-locked">🔒 Déplacements suspendus pendant cette séquence de mission.</p>':!host?'<p class="explore-locked">L’hôte contrôle les déplacements du groupe.</p>':'<p class="minor">Rencontres et activités locales, une fois par campagne.</p>'}
 ${locals.map(n=>`<div class="district-event"><div><b>💬 ${h(n.name)}</b><small>${h(n.role)}</small></div><button data-action="world-talk" data-value="${n.id}" ${!explore||!host||s.city?.met?.[n.id]?'disabled':''}>${s.city?.met?.[n.id]?'RENCONTRÉ':'PARLER'}</button></div>`).join('')}
 ${tasks.map(a=>`<div class="district-event"><div><b>${a.icon} ${h(a.name)}</b><small>${h(a.desc)}</small></div><button data-action="world-activity" data-value="${a.id}" ${!explore||!host||s.city?.activities?.[a.id]?'disabled':''}>${s.city?.activities?.[a.id]?'TERMINÉ':'ACCEPTER'}</button></div>`).join('')}
 </div></div><p class="explore-footnote">Le scénario principal continue uniquement lorsque vous choisissez une action de mission.</p></section>`;
}

function cityEconomy(s,online){const canManage=!online||!!ui.online?.isHost;const inv=s.inventory||{},district=W.currentDistrict(s),exploring=W.canExplore(s);const price=n=>n.toLocaleString('fr-FR')+' €';const disabled=online&&!canManage?'disabled title="Seul l’hôte peut gérer l’inventaire du groupe"':'';return `<section class="side-panel world-panel" id="inventaire-ville"><div class="eyebrow">RIVIERA · VOTRE INVENTAIRE</div><div class="world-wallet">💶 Caisse commune <strong>${price(s.stats.money)}</strong></div>${s.prepared?`<p class="world-ready">⚡ Bonus préparé : +${s.prepared.bonus} ${s.prepared.skills?'('+s.prepared.skills.map(x=>E.SKILL_LABEL[x]).join(' / ')+')':'au prochain jet'}</p>`:''}<div class="inventory-grid">${Object.keys(inv).filter(id=>inv[id]>0).map(id=>{const it=W.ITEMS.find(x=>x.id===id);if(!it)return '';return `<article class="inventory-item"><span class="world-icon">${it.icon}</span><div><b>${h(it.name)}</b><small>${h(it.desc)} · Quantité : ${inv[id]}</small></div><div class="world-actions">${it.kind==='gear'?`<button data-action="world-equip" data-value="${id}" ${disabled}>${s.equipped===id?'RETIRER':'ÉQUIPER'}</button>`:''}${['heal','boost'].includes(it.kind)?`<button data-action="world-use" data-value="${id}" ${disabled}>UTILISER</button>`:''}</div></article>`;}).join('')||'<p class="minor">Sac vide. Explorez les boutiques.</p>'}</div><details class="world-shop"><summary>🛒 MARCHANDS · ${h(district.name)}</summary>${W.STORES.filter(shop=>shop.districtId===district.id).map(shop=>`<div class="shop-section"><h4>${shop.icon} ${h(shop.name)} <small>${h(shop.district)}</small></h4><p>${h(shop.desc)}</p>${W.ITEMS.filter(x=>x.place===shop.id).map(it=>`<div class="shop-item"><span>${it.icon}</span><div><b>${h(it.name)}</b><small>${h(it.desc)}</small></div><button data-action="world-buy" data-value="${it.id}" ${s.stats.money<it.price||!canManage||!exploring?'disabled':''}>${price(it.price)}</button></div>`).join('')}</div>`).join('')}</details><details class="world-shop"><summary>🗺️ SERVICES · ${h(district.name)}</summary>${W.SERVICES.filter(it=>it.districtId===district.id).map(it=>`<div class="shop-item"><span>${it.icon}</span><div><b>${h(it.name)}</b><small>${h(it.desc)}</small></div><button data-action="world-service" data-value="${it.id}" ${s.stats.money<it.price||!canManage||!exploring||s.servicesUsed?.[s.scene+':'+it.id]?'disabled':''}>${price(it.price)}</button></div>`).join('')}</details>${online&&!canManage?'<p class="minor">L’hôte valide les dépenses pour éviter les achats concurrents.</p>':''}</section>`;}
function play(){const s=ui.game;if(!s)return menu();const scene=E.getScene(s);const picture=artFor(s.scene);const online=ui.mode==='online';const roster=online?(ui.online?.players||[]):ui.mode==='local'?E.HEROES.slice(0,ui.count).map((x,i)=>({character:ui.game?.crew?.find(y=>y.id==='perso_local_'+i)?.id||x.id,name:ui.names[i],id:'p'+i,profile:ui.game?.crew?.find(y=>y.id==='perso_local_'+i)||null})):E.HEROES.map(x=>({character:x.id,name:x.name,id:x.id})).concat(ui.game?.crew?.filter(x=>x.custom).map(x=>({character:x.id,name:x.name,id:x.id,profile:x}))||[]);const ready=ui.mode==='local'&&Object.keys(ui.localVotes).length>=ui.count;
const current=ui.mode==='local'?roster[Math.min(ui.localTurn,roster.length-1)]:null;
const roleOfVote=ui.mode==='local'?hero(current?.character||'gauthier'):ui.mode==='online'?hero(ui.online?.me?.character||ui.hero):hero(ui.actor);
return `${header()}<main class="game-layout"><div class="main-column"><section class="scene-box"><div class="scene-banner" style="--scene-art:url('${asset(picture)}')"><div class="scene-art-credit">● RIVIERA / ${h(s.mission||'neree').toUpperCase()}</div><div class="loc-top"><span class="red-dot"></span>${h(scene.location)}</div><div class="scene-overline">${h(scene.chapter)}</div><h1>${h(scene.title)}</h1><div class="decor-lines"></div></div><div class="scene-copy">${scene.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}</div><div class="city-shortcut"><a href="#explorer-riviera">🗺️ CARTE & DÉPLACEMENTS ↓</a> · <a href="#inventaire-ville">🎒 INVENTAIRE ↓</a></div></section>${cityMap(s,online)}
${s.last?`<div class="outcome ${s.last.success===null?'neutral':s.last.success?'win':'loss'}"><div class="outcome-head"><span>${s.last.skill?(s.last.success?'✓ RÉUSSITE':'✕ ÉCHEC'):'◆ CHOIX EFFECTUÉ'}</span>${s.last.skill?`<strong>⚄ 2D6 ${s.last.roll} + ${s.last.total-s.last.roll} = ${s.last.total} / ${s.last.dc}</strong>`:''}</div><p>${h(s.last.note||'Votre décision est prise en compte.')}</p><small>${h(s.last.actor)} · ${h(s.last.choice)}</small></div>`:''}
<section class="decisions"><div class="section-heading"><span>${scene.isEnding?'ÉPILOGUE':'DÉCISION COLLECTIVE'}</span><h2>${scene.isEnding?'Votre histoire ne fait que commencer.':ui.mode==='local'?ready?'Le groupe a voté':`Au tour de ${h(current.name)}`:online?'Quel choix défendez-vous ?':'Quelle sera votre décision ?'}</h2></div>
${!scene.isEnding&&ui.mode==='solo'?`<div class="actor-row"><span>Personnage actif :</span>${E.HEROES.concat(ui.game?.crew?.filter(x=>x.custom)||[]).map(x=>`<button class="actor-chip ${ui.actor===x.id?'active':''}" data-action="actor" data-value="${x.id}"><span style="background:${x.color}"></span>${x.name}</button>`).join('')}</div>`:''}
${!scene.isEnding&&ui.mode==='local'&&!ready?`<div class="vote-notice">Vote ${ui.localTurn+1}/${ui.count} — ${h(current.name)} joue ${h(roleOfVote.role)}.</div>`:''}
${!scene.isEnding&&online?`<div class="vote-notice">${ui.online?.votedCount||0} / ${ui.online?.eligibleCount||roster.length} votes reçus. ${ui.ownVote?'Vous avez voté. Vous pouvez encore changer.':'Choisissez une option.'}</div>`:''}
<div class="choices">${scene.choices.filter(c=>c.condition!==false).map((c,i)=>`<button class="choice ${online&&ui.ownVote===c.id?'chosen':''}" data-action="choice" data-value="${c.id}" ${ready?'disabled':''}><span class="choice-index">0${i+1}</span><span class="choice-body"><b>${h(c.title)}</b><small>${h(c.description)}</small>${c.skill?`<span class="skill-tag">⚄ ${h(E.SKILL_LABEL[c.skill])} · SEUIL ${E.dcFor(c,s.difficulty)} ${ui.mode==='solo'?`· BONUS +${(roleOfVote.skills?.[c.skill]||0)+(roleOfVote.specialty===c.skill?1:0)}`:''}</span>`:'<span class="skill-tag automatic">DÉCISION</span>'}</span><span class="choice-arrow">↗</span></button>`).join('')}</div>
${ui.mode==='local'&&ready?`<div class="resolve-panel"><div class="resolve-votes">${scene.choices.map(c=>{const n=Object.values(ui.localVotes).filter(id=>id===c.id).length;return n?`<span>${h(c.title)} <b>${n} vote${n>1?'s':''}</b></span>`:'';}).join('')}</div><button class="btn btn-primary" data-action="resolve-local">RÉSOUDRE LES VOTES ET LANCER LES DÉS ⚄</button></div>`:''}
${online&&ui.online?.isHost&&!scene.isEnding?`<div class="resolve-panel"><button class="btn btn-primary" data-action="resolve-online" ${ui.online?.votedCount!==(ui.online?.eligibleCount||roster.length)?'disabled':''}>VALIDER LE CHOIX COLLECTIF ⚄</button><small>${ui.online?.votedCount!==(ui.online?.eligibleCount||roster.length)?'En attente des votes des joueurs connectés.':'Vous pouvez valider le résultat.'}</small></div>`:''}
${scene.isEnding?`<div class="end-actions">${s.ended?'<button class="btn btn-primary" data-action="next-mission">CONTINUER LA CAMPAGNE →</button>':''}<button class="btn btn-outline" data-action="replay">REJOUER ↺</button><button class="btn btn-outline" data-action="home">RETOUR À L’ACCUEIL</button></div>`:''}
</section></div>
<aside class="sidebar"><section class="side-panel objective"><div class="eyebrow">OBJECTIF ACTUEL</div><p>${h(scene.objective)}</p><div class="progress"><span>${h((E.MISSIONS.find(m=>m.id===s.mission)||{name:"CARTE DES MISSIONS"}).name)}</span><span>ÉTAPE ${s.round+1}</span></div></section>
${online?`<section class="side-panel room-info"><div class="eyebrow">SALON EN LIGNE</div><div class="room-id">${h(ui.online?.room||'——')} <button data-action="copy-code" title="Copier le code">⧉</button></div><button class="btn btn-subtle btn-block btn-xs" data-action="copy-link">COPIER LE LIEN D’INVITATION ⧉</button>${ui.online?.isHost?'<button class="btn btn-outline btn-block btn-xs" data-action="export-campaign">↓ EXPORTER UNE COPIE DE LA CAMPAGNE</button>':''}${ui.online?.isHost&&ui.online?.recoveryKey?`<div class="recovery-key"><small>CLÉ PRIVÉE DE REPRISE — NE PAS PARTAGER</small><code>${h(ui.online.recoveryKey)}</code><button data-action="copy-recovery" class="btn btn-outline btn-xs">COPIER LA CLÉ</button></div>`:''}<small>${ui.online?.isHost?'Vous êtes l’hôte. Vous validez les décisions.':'L’hôte valide les décisions.'} ${roster.filter(p=>!p.connected).length?'Un joueur est hors ligne et pourra revenir.':''}</small></section>`:''}
<section class="side-panel"><div class="eyebrow">L’ÉTAT DE RIVIERA</div>${miniStat('Pression / recherche',s.stats.heat,'heat')}${miniStat('Lucien / confiance',s.stats.lucien,'lucien')}${miniStat('Police / soutien',s.stats.police,'police')}${miniStat('Trésorerie',s.stats.money,'money')}${miniStat('Cohésion du groupe',s.stats.morale,'morale')}</section>
${cityEconomy(s,online)}
<section class="side-panel"><div class="eyebrow">PIÈCES À CONVICTION</div><div class="evidence-list"><div><span>▧</span> Nérée — Volume I <b>${s.flags.half?'ACQUIS':'MANQUANT'}</b></div><div><span>▧</span> Nérée — Volume II <b class="${s.flags.full?'ok':'pending'}">${s.flags.full?'ACQUIS':'MANQUANT'}</b></div>${s.flags.watch?'<div><span>◷</span> Objet issu d’une improvisation <b class="ok">DÉTENU</b></div>':''}<div><span>✦</span> Pistes identifiées <b>${E.leads(s)}/3</b></div></div></section>
<section class="side-panel"><div class="eyebrow">L’ÉQUIPE</div><div class="crew-list">${roster.map(p=>{const x=p.profile||hero(p.character);const voted=ui.mode==='online'?(ui.online?.votedIds||[]).includes(p.id):ui.mode==='local'?!!ui.localVotes[p.id]:false;return `<div class="crew-member"><span class="avatar sm photo" style="--hero:${x.color}">${portraitFor(p.profile||x)}</span><span><b>${h(p.profile?.name||p.name)}</b><small>${h(x.role)}</small></span>${ui.mode!=='solo'?`<span class="member-status">${voted?'✓':'○'}</span>`:''}</div>`;}).join('')}</div></section>
<section class="side-panel"><div class="eyebrow">CARNET DE BORD</div><div class="journal">${s.journal.slice(0,5).map(j=>`<div><b>${h(j.title)}</b><p>${h(j.text)}</p></div>`).join('')}</div></section>
${!online?'<button class="btn btn-subtle btn-block" data-action="reset">↺ Nouvelle partie</button>':''}
</aside></main>${ui.notice?`<div class="toast">${h(ui.notice)}</div>`:''}${ui.error?`<div class="toast error">${h(ui.error)}</div>`:''}${rules()}`;}
function lobby(){const online=ui.online;if(!online)return menu();return `${header()}<main class="lobby"><div class="eyebrow">MULTIJOUEUR · SALON PRIVÉ</div><h1>Le groupe se rassemble.</h1><p>Partagez ce code avec les autres joueurs. Chacun choisit un personnage encore disponible, puis l’hôte commence la mission.</p>${online.isHost&&online.recoveryKey?`<div class="recovery-key"><small>CONSERVEZ CETTE CLÉ POUR RETROUVER LA PARTIE PLUS TARD</small><code>${h(online.recoveryKey)}</code><button data-action="copy-recovery" class="btn btn-outline btn-xs">COPIER LA CLÉ PRIVÉE</button></div>`:''}<div class="big-code">${h(online.room)} <button class="btn btn-outline" data-action="copy-link">COPIER LE LIEN À PARTAGER ⧉</button></div><div class="lobby-roster">${online.players.map(p=>{const x=hero(p.character);return `<div class="lobby-player"><span class="avatar photo" style="--hero:${x.color}">${portraitFor(p.profile||x)}</span><div><b>${h(p.profile?.name||p.name)}</b><small>${h(x.name)} · ${h(x.role)} · ${p.connected?'CONNECTÉ':'DÉCONNECTÉ'}</small></div>${p.id===online.hostId?'<span class="host-label">HÔTE</span>':''}</div>`;}).join('')}${Array.from({length:Math.max(0,4-online.players.length)},()=>'<div class="empty-player">+ EN ATTENTE D’UN JOUEUR</div>').join('')}</div>${online.isHost?`<div class="backup-import"><label>↥ IMPORTER UNE ANCIENNE CAMPAGNE <input type="file" data-field="import-file" accept=".json,application/json"/></label><small>${online.imported?'✓ Campagne importée : vous pouvez commencer.':'Importez une copie .json, puis invitez les joueurs.'}</small></div><button class="btn btn-primary btn-large" data-action="start-online" ${(online.eligibleCount||0)<2?'disabled':''}>LANCER LA MISSION ↗</button><p class="minor">${online.players.length<2?'Il faut au moins deux joueurs pour lancer une partie multijoueur.':'Tous les joueurs sont prêts à entrer dans l’histoire.'}</p>`:'<div class="vote-notice">En attente du lancement par l’hôte…</div>'}<button class="btn btn-subtle" data-action="home">Quitter le salon</button>${ui.error?`<p class="warning">${h(ui.error)}</p>`:''}</main>${rules()}`;}

function aiLobby(){
 const room=ui.online||{},canStart=room.aiReady&&(room.eligibleCount||0)>=1;
 return `${header()}<main class="lobby"><div class="eyebrow">MODE MJ IA · SALON NARRATIF</div><h1>Votre MJ vous attend.</h1><p>La partie commence avant la rencontre avec Lucien. Vous pouvez jouer seul ou inviter jusqu’à trois autres personnes. Chaque joueur décrit librement ses actions.</p>
 <div class="big-code">${h(room.room||'')} <button class="btn btn-outline" data-action="copy-link">COPIER LE LIEN À PARTAGER ⧉</button></div>
 ${room.isHost&&room.recoveryKey?`<div class="recovery-key"><small>CLÉ PRIVÉE POUR RÉCUPÉRER LA PARTIE</small><code>${h(room.recoveryKey)}</code><button class="btn btn-outline btn-xs" data-action="copy-recovery">COPIER LA CLÉ</button></div>`:''}
 <div class="lobby-roster">${(room.players||[]).map(p=>'<div class="lobby-player"><b>'+h(p.profile?.name||p.name)+'</b><small>'+(p.connected?'● PRÉSENT':'○ HORS LIGNE')+'</small></div>').join('')}</div>
 ${room.isHost?`<div class="backup-import"><label>↥ IMPORTER UNE CAMPAGNE MJ IA <input type="file" data-field="import-file" accept=".json,application/json"/></label><small>${room.imported?'✓ Campagne importée et prête à reprendre.':'Réutilisez un export de cette campagne MJ IA.'}</small></div><button class="btn btn-primary btn-large" data-action="start-online" ${canStart?'':'disabled'}>LANCER LA CAMPAGNE AVEC LE MJ IA ✦</button>`:'<div class="vote-notice">En attente du lancement par l’hôte…</div>'}
 ${!room.aiReady?'<p class="warning">Le moteur IA est installé mais n’est pas encore activé. Configurez OPENAI_API_KEY dans Render pour jouer.</p>':''}
 <button class="btn btn-subtle" data-action="home">Quitter le salon</button>${ui.error?`<p class="warning">${h(ui.error)}</p>`:''}</main>`;
}
function aiPlay(){
 const online=ui.online||{},ai=online.ai||{},game=ui.game||{},log=ai.log||[];
 return `${header()}<main class="ai-layout"><section class="ai-main"><div class="ai-hero"><span class="eyebrow">MJ IA · SCÉNARIO FIDÈLE</span><h1>La Nuit du Belladone</h1><p>Décrivez ce que vous faites. Le MJ improvise en respectant notre scénario et les résultats des dés.</p><span class="ai-stage">📍 ${h(ai.stage||'Premier contact')}</span></div>
 <div class="ai-thread" role="log" aria-label="Récit de la partie">${log.map(m=>'<article class="ai-message ai-'+(m.kind==='mj'?'gm':m.kind==='des'?'dice':'player')+'"><div class="ai-author">'+(m.kind==='mj'?'✦ Maître du jeu':m.kind==='des'?'⚄ Jet de dés':h(m.who||'Joueur'))+'</div><p>'+h(m.text)+'</p></article>').join('')}
 ${ai.busy?'<div class="ai-thinking">✦ Le MJ réfléchit aux conséquences de cette action…</div>':''}</div>
 <div class="ai-compose"><label for="ai-draft">Votre action libre</label><textarea id="ai-draft" data-field="ai-draft" maxlength="500" rows="3" placeholder="Ex. : Je vais discrètement observer le garage avant le rendez-vous.">${h(ui.aiDraft)}</textarea><div class="ai-compose-bottom"><small>2D6 gérés par le serveur · ${ai.turns||0}/80 tours</small><button class="btn btn-primary" data-action="ai-send" ${ai.busy||!ui.aiDraft.trim()?'disabled':''}>ENVOYER MON ACTION ↗</button></div></div>
 ${ui.error?`<p class="warning">${h(ui.error)}</p>`:''}</section>
 <aside class="ai-aside"><section class="side-panel"><div class="eyebrow">L’ÉQUIPE</div>${(online.players||[]).map(p=>'<div class="ai-player"><b>'+h(p.profile?.name||p.name)+'</b><small>'+(p.connected?'● connecté':'○ hors ligne')+'</small></div>').join('')}</section><section class="side-panel"><div class="eyebrow">ÉTAT DU GROUPE</div><p>💶 Argent : <strong>${Number(game.stats?.money||0).toLocaleString('fr-FR')} €</strong></p><p>🚨 Pression : <strong>${game.stats?.heat??0}/10</strong></p><p>🤝 Cohésion : <strong>${game.stats?.morale??0}/5</strong></p><p>🎒 Inventaire : ${h(Object.entries(game.inventory||{}).filter(x=>x[1]>0).map(x=>(W.ITEMS.find(i=>i.id===x[0])?.name||x[0])+' ×'+x[1]).join(', ')||'Vide')}</p></section><section class="side-panel"><div class="eyebrow">SALON PRIVÉ</div><p>Code : <strong>${h(online.room||'')}</strong></p><button class="btn btn-outline btn-xs" data-action="copy-link">COPIER L’INVITATION</button>${online.isHost?'<button class="btn btn-outline btn-xs" data-action="export-campaign">↓ EXPORTER LA CAMPAGNE</button>':''}${online.isHost?'<button class="btn btn-subtle btn-xs" data-action="replay">RECOMMENCER</button>':''}</section><button class="btn btn-subtle" data-action="home">← MENU</button></aside></main>`;
}

function render(){app.innerHTML=ui.page==='creator'?creator():ui.page==='menu'?menu():ui.page==='lobby'?(ui.online?.aiMode?aiLobby():lobby()):(ui.online?.aiMode?aiPlay():play());}
function newGame(){if(ui.mode!=='local'&&ui.hero==='custom'&&(!ui.customProfile.name.trim()||!validSkills(ui.customProfile)||!ui.customProfile.contactId||!ui.customProfile.flawId)){ui.page='creator';ui.creatorFor='solo';ui.error='Complétez votre fiche, notamment un contact et un défaut, pour commencer.';render();return;}ui.game=E.createGame(ui.difficulty,ui.selectedMission);if(ui.mode==='local'){E.prepareCrew(ui.game,Object.entries(ui.localCustom).map(([i,x])=>makeProfile(x,'perso_local_'+i)));}else if(ui.hero==='custom'){E.prepareCrew(ui.game,[makeProfile(ui.customProfile)]);}ui.localVotes={};ui.localTurn=0;ui.actor=ui.hero==='custom'?'perso_solo':ui.hero;ui.page='play';ui.error='';save();render();}
function majority(votes,s){const tally={};Object.values(votes).forEach(v=>tally[v]=(tally[v]||0)+1);const max=Math.max(0,...Object.values(tally));const tied=Object.keys(tally).filter(k=>tally[k]===max);const firstVote=votes['p0'];const picked=tied.includes(firstVote)?firstVote:tied[0];const option=E.getScene(s).choices.find(c=>c.id===picked);let actors=E.HEROES.slice(0,ui.count).map((x,i)=>s.crew?.find(y=>y.id==='perso_local_'+i)||x).filter((x,i)=>votes['p'+i]===picked);actors.sort((a,b)=>(option?.skill?b.skills[option.skill]-a.skills[option.skill]:0));return{picked,actor:actors[0]?.id||'gauthier'};}
function decide(id,actor){try{ui.game=E.choose(ui.game,id,actor);ui.localVotes={};ui.localTurn=0;save();render();window.scrollTo({top:0,behavior:'smooth'});}catch(err){ui.error=err.message;render();}}
function connect(kind){if(!hasServer){ui.error='Pour jouer en ligne, utilisez le serveur inclus dans le ZIP.';render();return;}const name=ui.nickname.trim()|| (ui.hero==='custom'?ui.customProfile.name:hero(ui.hero).name);if(kind!=='resume'&&kind!=='recover'&&ui.hero==='custom'&&(!ui.customProfile.name.trim()||!validSkills(ui.customProfile)||!ui.customProfile.contactId||!ui.customProfile.flawId)){ui.error='Créez votre personnage, avec un contact et un défaut, avant de jouer.';render();return;}const room=kind==='resume'?(ui.onlineSession?.room||''):ui.joinCode.trim().toUpperCase().replace(/[^A-Z0-9]/g,'');if((kind==='join'||kind==='recover')&&!room){ui.error='Saisissez le code du salon.';render();return;}ui.error='';ui.notice='Connexion au salon…';render();try{ui.ws?.close();const ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host);ui.ws=ws;ws.addEventListener('open',()=>ws.send(JSON.stringify({type:kind==='create'?'create':kind==='resume'?'resume':kind==='recover'?'recover':'join',name,character:ui.hero,profile:ui.hero==='custom'?ui.customProfile:null,aiMode:ui.aiMode,recoveryKey:ui.recoveryKey,room,token:ui.onlineSession?.token,difficulty:ui.difficulty,mission:ui.selectedMission})));ws.addEventListener('message',(e)=>{let msg;try{msg=JSON.parse(e.data);}catch{return;}if(msg.type==='error'){ui.error=msg.message;ui.notice='';if(kind==='resume'){ui.page='menu';ui.onlineSession=null;try{localStorage.removeItem(LS_ROOM);}catch(e){}}render();}else if(msg.type==='snapshot'){if(ui.game&&msg.data.game&&ui.game.round!==msg.data.game.round)ui.ownVote=null;ui.online={...msg.data,me:msg.data.players.find(p=>p.id===msg.data.you),isHost:msg.data.hostId===msg.data.you};ui.reconnecting=false;ui.mode='online';ui.aiMode=!!msg.data.aiMode;ui.notice='';ui.error=msg.data.aiMode?ui.error:'';if(msg.data.game){ui.game=msg.data.game;ui.page='play';}else ui.page='lobby';render();}else if(msg.type==='backup'){const content=JSON.stringify(msg.data,null,2);const blob=new Blob([content],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='gta-riviera-'+(ui.online?.room||'campagne')+'-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);ui.notice='Copie de sauvegarde téléchargée';render();}else if(msg.type==='registered'){ui.onlineSession={token:msg.token,room:msg.room};try{localStorage.setItem(LS_ROOM,JSON.stringify(ui.onlineSession));}catch(e){}}else if(msg.type==='info'){ui.notice=msg.message;render();}});ws.addEventListener('close',()=>{if(ui.ws!==ws)return;if(ui.mode==='online'&&ui.page!=='menu'&&ui.onlineSession&&!ui.reconnecting){ui.reconnecting=true;ui.notice='Connexion perdue : reconnexion automatique…';render();setTimeout(()=>{if(ui.mode==='online'&&ui.page!=='menu'&&ui.reconnecting)connect('resume');},1800);}});ws.addEventListener('error',()=>{ui.error='Connexion impossible : vérifiez que le serveur est démarré.';ui.notice='';render();});}catch(e){ui.error=e.message;render();}}
function send(type,extra={}){if(!ui.ws||ui.ws.readyState!==WebSocket.OPEN){ui.error='Connexion au serveur indisponible.';render();return;}ui.ws.send(JSON.stringify({type,...extra}));}
function home(){if(ui.mode==='online'){ui.reconnecting=false;ui.onlineSession=null;try{localStorage.removeItem(LS_ROOM);}catch(e){}try{ui.ws?.close();}catch(e){}ui.online=null;ui.game=null;ui.ownVote=null;}ui.page='menu';ui.notice='';ui.error='';render();}
app.addEventListener('input',(ev)=>{const el=ev.target;const fld=el.dataset.field;if(!fld)return;if(fld==='ai-draft')ui.aiDraft=el.value;else if(fld==='nickname')ui.nickname=el.value;else if(fld==='recoveryKey')ui.recoveryKey=el.value.toUpperCase();else if(fld==='profile-name'){ui.customProfile.name=el.value;storeProfile();}else if(fld==='profile-bio'){ui.customProfile.bio=el.value;storeProfile();}else if(fld==='profile-nickname'){ui.customProfile.nickname=el.value;storeProfile();}else if(fld==='profile-contacts'){ui.customProfile.contacts=el.value;storeProfile();}else if(fld==='profile-notes'){ui.customProfile.notes=el.value;storeProfile();}else if(fld==='profile-equipment'){ui.customProfile.equipment=el.value;storeProfile();}else if(fld==='profile-goal'){ui.customProfile.goal=el.value;storeProfile();}else if(fld==='profile-flaw'){ui.customProfile.flaw=el.value;storeProfile();}else if(fld==='joinCode')ui.joinCode=el.value.toUpperCase();else if(fld.startsWith('name-'))ui.names[+fld.split('-')[1]]=el.value;const finish=app.querySelector('[data-action="finish-creator"]');if(finish)finish.disabled=!(ui.customProfile.name.trim()&&validSkills(ui.customProfile)&&ui.customProfile.contactId&&ui.customProfile.flawId);if(fld==='ai-draft'){const sendButton=app.querySelector('[data-action="ai-send"]');if(sendButton)sendButton.disabled=!ui.aiDraft.trim()||!!ui.online?.ai?.busy;}});
app.addEventListener('change',async ev=>{if(ev.target?.dataset.field==='profile-archetype'){ui.customProfile.archetype=ev.target.value;storeProfile();return;}if(ev.target?.dataset.field!=='import-file')return;const f=ev.target.files?.[0];if(!f)return;try{if(f.size>150000)throw Error('Sauvegarde trop volumineuse');const backup=JSON.parse(await f.text());send('import',{backup});}catch(e){ui.error='Import impossible : '+e.message;render();}});
app.addEventListener('click',(ev)=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value;ui.error='';if(a==='ai-send'){const action=ui.aiDraft.trim();if(action&&!ui.online?.ai?.busy){send('ai_action',{text:action});ui.aiDraft='';render();}}else if(a==='ai-mode'){ui.mode='online';ui.aiMode=true;ui.onlineAction='create';render();}else if(a?.startsWith('world-')){const action=a.slice(6);if(ui.mode==='online')send('world',{action,id:v});else{try{ui.game=E.worldAction(ui.game,action,v);save();ui.notice='Action effectuée dans Riviera.';}catch(err){ui.error=err.message;}}render();}else if(a==='profile-contact'){ui.customProfile.contactId=v;storeProfile();render();}else if(a==='profile-flaw-id'){ui.customProfile.flawId=v;storeProfile();render();}else if(a==='open-creator'){ui.creatorFor='solo';ui.page='creator';ui.hero='custom';render();}else if(a==='open-local-creator'){ui.creatorFor='local';ui.page='creator';render();}else if(a==='creator-back'){ui.page='menu';render();}else if(a==='finish-creator'){if(!ui.customProfile.name.trim()||!validSkills(ui.customProfile)||!ui.customProfile.contactId||!ui.customProfile.flawId){ui.error='Fiche incomplète : nom, caractéristiques, contact et défaut requis.';render();return;}storeProfile();if(ui.creatorFor==='local'){ui.localCustom[ui.localTarget]=makeProfile(ui.customProfile,'perso_local_'+ui.localTarget);ui.localEditing=false;}else{ui.hero='custom';}ui.page='menu';render();}else if(a==='mode'){ui.mode=v;ui.aiMode=false;render();}else if(a==='mission'){ui.selectedMission=v;render();}else if(a==='hero'){ui.hero=v;if(v==='custom'){ui.creatorFor='solo';ui.page='creator';}render();}else if(a==='profile-portrait'){ui.customProfile.portrait=v;storeProfile();render();}else if(a==='profile-color'){ui.customProfile.color=v;storeProfile();render();}else if(a==='profile-specialty'){ui.customProfile.specialty=v;storeProfile();render();}else if(a==='profile-plus'||a==='profile-minus'){const increment=a==='profile-plus'?1:-1;const current=ui.customProfile.skills[v];if(Number.isInteger(current)&&current+increment>=0&&current+increment<=2&&(increment<0||pointsLeft()>0)){ui.customProfile.skills[v]+=increment;storeProfile();render();}}else if(a==='toggle-local-editor'){ui.localEditing=!ui.localEditing;render();}else if(a==='local-target'){ui.localTarget=Number(v);render();}else if(a==='local-assign'){if(!ui.customProfile.name.trim()||!validSkills(ui.customProfile)||!ui.customProfile.contactId||!ui.customProfile.flawId){ui.error='Donnez un nom et une fiche +2/+1/+1/0/0.';render();return;}ui.localCustom[ui.localTarget]=makeProfile(ui.customProfile,'perso_local_'+ui.localTarget);ui.localEditing=false;render();}else if(a==='actor'){ui.actor=v;render();}else if(a==='difficulty'){ui.difficulty=v;render();}else if(a==='count'){ui.count=range(ui.count+parseInt(v,10),2,4);render();}else if(a==='online-action'){ui.onlineAction=v;render();}else if(a==='rules'){ui.showRules=!ui.showRules;render();}else if(a==='start'){if(ui.mode==='online')connect(ui.onlineAction);else newGame();}else if(a==='continue'){const saved=load();if(saved){Object.assign(ui,{game:saved.game,mode:saved.mode,hero:saved.hero,actor:saved.actor,names:saved.names,count:saved.count,difficulty:saved.difficulty,customProfile:saved.customProfile||ui.customProfile,localCustom:saved.localCustom||{},localVotes:saved.localVotes||{},localTurn:saved.localTurn||0,page:'play'});render();}}else if(a==='choice'){if(ui.mode==='solo')decide(v,ui.actor);else if(ui.mode==='local'){if(Object.keys(ui.localVotes).length>=ui.count)return;ui.localVotes['p'+ui.localTurn]=v;ui.localTurn++;save();render();}else{ui.ownVote=v;send('vote',{choice:v});render();}}else if(a==='resolve-local'){const {picked,actor}=majority(ui.localVotes,ui.game);decide(picked,actor);}else if(a==='resolve-online'){send('resolve');}else if(a==='start-online'){send('start');}else if(a==='export-campaign'){send('backup');}else if(a==='copy-recovery'){const key=ui.online?.recoveryKey;if(key&&navigator.clipboard?.writeText)navigator.clipboard.writeText(key).then(()=>{ui.notice='Clé privée copiée';render();});}else if(a==='copy-code'){const code=ui.online?.room||'';if(navigator.clipboard?.writeText)navigator.clipboard.writeText(code).then(()=>{ui.notice='Code copié : '+code;render();}).catch(()=>{});else{ui.notice='Code du salon : '+code;render();}}else if(a==='copy-link'){const url=location.origin+location.pathname+'?salon='+encodeURIComponent(ui.online?.room||'');if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url).then(()=>{ui.notice='Lien d’invitation copié';render();});else{ui.notice=url;render();}}else if(a==='home')home();else if(a==='next-mission'){if(ui.mode==='online')send('continue');else{ui.game=E.continueCampaign(ui.game);ui.localVotes={};ui.localTurn=0;save();render();}}else if(a==='replay'){if(ui.mode==='online'){ui.ownVote=null;send('restart');}else newGame();}else if(a==='reset'){if(confirm('Recommencer la campagne depuis le début ?'))newGame();}});
try{const storedProfile=JSON.parse(localStorage.getItem(LS_PROFILE)||'null');if(storedProfile&&typeof storedProfile.name==='string'&&storedProfile.skills&&validSkills(storedProfile)&&Object.keys(E.SKILL_LABEL).every(k=>Number.isInteger(storedProfile.skills[k])&&storedProfile.skills[k]>=0&&storedProfile.skills[k]<=2)){ui.customProfile=storedProfile;}}catch(e){}
try{const params=new URLSearchParams(location.search);const code=params.get('salon');if(code&&/^[A-Z2-9]{5}$/.test(code.toUpperCase())){ui.mode='online';ui.onlineAction='join';ui.joinCode=code.toUpperCase();}else if(hasServer){const stored=JSON.parse(localStorage.getItem(LS_ROOM)||'null');if(stored?.room&&stored?.token){ui.onlineSession=stored;ui.mode='online';}}}catch(e){}
render();if(ui.onlineSession&&hasServer)connect('resume');
})();
